-- =============================================================================
-- ⚠  DESTRUCTIVE — DELETES THE ENTIRE `myenterprise` DATABASE, THEN REBUILDS IT
-- 
-- Every order, customer and change made through the shop or admin is lost and
-- replaced by the original sample data. Only the `myenterprise` database is
-- touched; other databases on the server are not. Use it to reset the demo
-- before a presentation. (generated by tools/build-sql.mjs)
-- =============================================================================

DROP DATABASE IF EXISTS myenterprise;

-- >>> 00_create_database.sql
-- =============================================================================
-- MyEnterprise — fashion commerce database
-- File 00: create the database (non-destructive)
-- -----------------------------------------------------------------------------
-- Creates the `myenterprise` database only if it does not already exist.
-- It never drops anything. To rebuild from scratch, use the clearly labelled
-- reset script in database/reset/ instead.
--
-- Supported engine: MariaDB 10.4 or newer (tested on 10.4.28, the version in
-- XAMPP 8.2). MySQL 8 is not tested; see docs/DATABASE.md, "Engine notes".
-- Import order (phpMyAdmin → Import, or the mysql CLI):
--   00_create_database.sql → 01_schema.sql → 02_functions.sql →
--   03_procedures.sql → 04_triggers.sql → 05_views.sql → 06_seed_data.sql
-- Or import the single combined file: database/myenterprise_full.sql
-- =============================================================================

CREATE DATABASE IF NOT EXISTS myenterprise
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_general_ci;

USE myenterprise;


-- >>> 01_schema.sql
-- =============================================================================
-- MyEnterprise — fashion commerce database
-- File 01: schema — 31 tables, keys, CHECK constraints and indexes
-- -----------------------------------------------------------------------------
-- Source of truth: "MyEnterprise | Logical Table Diagram — 30 Tables".
-- Table and column names follow the diagram exactly, with these documented
-- changes (see docs/DECISIONS.md, "Schema changes"):
--   * `Order` is created as CustomerOrder, because ORDER is a reserved SQL word.
--   * Columns marked  -- [added]  are not in the diagram. Each one is needed by
--     a workflow the diagram describes (login, shipping address, delivery dates,
--     audit times, idempotency). No original column was removed or renamed.
--   * One table is added: ProductImage (pictures stored as binary data), so a
--     product photograph is uploaded straight into the database.
--   * Fulfillment.admin_id and OrderCancellation.cancelledBy are nullable:
--     a fulfillment exists before an admin picks it up, and customers may
--     cancel their own orders.
--
-- Conventions
--   * InnoDB everywhere (transactions + foreign keys), utf8mb4.
--   * Money is DECIMAL(10,2); never FLOAT.
--   * Status columns hold UPPER_CASE codes guarded by CHECK constraints.
--   * Financial and stock history is never cascaded away: ON DELETE RESTRICT.
--     Catalog detail rows (specs, category links) cascade with their parent.
-- =============================================================================

USE myenterprise;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 1;

-- -----------------------------------------------------------------------------
-- CORE
-- -----------------------------------------------------------------------------

CREATE TABLE Customer (
  customer_id    INT          NOT NULL AUTO_INCREMENT,
  email          VARCHAR(100) NOT NULL,
  firstName      VARCHAR(50)  NOT NULL,
  lastName       VARCHAR(50)  NOT NULL,
  phone          VARCHAR(20)  NULL,
  password_hash  VARCHAR(255) NOT NULL,                              -- [added] bcrypt/argon2 hash, never plaintext
  createdAt      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,    -- [added]
  CONSTRAINT pk_customer PRIMARY KEY (customer_id),
  CONSTRAINT uq_customer_email UNIQUE (email),
  CONSTRAINT chk_customer_email CHECK (email LIKE '%_@_%._%'),
  CONSTRAINT chk_customer_names CHECK (CHAR_LENGTH(TRIM(firstName)) > 0 AND CHAR_LENGTH(TRIM(lastName)) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Registered shoppers';

CREATE TABLE Admin (
  admin_id       INT          NOT NULL AUTO_INCREMENT,
  email          VARCHAR(100) NOT NULL,
  role           VARCHAR(30)  NOT NULL,
  fullName       VARCHAR(100) NOT NULL,                              -- [added] shown in audit trails
  password_hash  VARCHAR(255) NOT NULL,                              -- [added]
  isActive       BOOLEAN      NOT NULL DEFAULT TRUE,                 -- [added] disable without deleting history
  createdAt      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,    -- [added]
  CONSTRAINT pk_admin PRIMARY KEY (admin_id),
  CONSTRAINT uq_admin_email UNIQUE (email),
  CONSTRAINT chk_admin_role CHECK (role IN ('ADMINISTRATOR', 'OPERATIONS', 'CATALOG', 'SUPPORT')),
  CONSTRAINT chk_admin_email CHECK (email LIKE '%_@_%._%')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Store staff; role drives what the admin API allows';

-- -----------------------------------------------------------------------------
-- CATALOG
-- -----------------------------------------------------------------------------

CREATE TABLE Category (
  category_id     INT          NOT NULL AUTO_INCREMENT,
  category_name   VARCHAR(80)  NOT NULL,
  slug            VARCHAR(80)  NOT NULL,                             -- [added] URL key
  category_group  VARCHAR(20)  NOT NULL DEFAULT 'TYPE',              -- [added] DEPARTMENT / TYPE / COLLECTION
  sortOrder       SMALLINT     NOT NULL DEFAULT 0,                   -- [added] navigation order
  CONSTRAINT pk_category PRIMARY KEY (category_id),
  CONSTRAINT uq_category_name UNIQUE (category_name),
  CONSTRAINT uq_category_slug UNIQUE (slug),
  CONSTRAINT chk_category_group CHECK (category_group IN ('DEPARTMENT', 'TYPE', 'COLLECTION')),
  CONSTRAINT chk_category_slug CHECK (slug REGEXP '^[a-z0-9]+(-[a-z0-9]+)*$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Departments (Women, Men), garment types and editorial collections';

CREATE TABLE Product (
  product_id   INT           NOT NULL AUTO_INCREMENT,
  admin_id     INT           NOT NULL,
  name         VARCHAR(100)  NOT NULL,
  brand        VARCHAR(80)   NOT NULL,
  description  TEXT          NOT NULL,
  isActive     BOOLEAN       NOT NULL DEFAULT TRUE,
  slug         VARCHAR(120)  NOT NULL,                               -- [added] URL key
  createdAt    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,     -- [added] "New in" ordering
  CONSTRAINT pk_product PRIMARY KEY (product_id),
  CONSTRAINT uq_product_slug UNIQUE (slug),
  CONSTRAINT fk_product_admin FOREIGN KEY (admin_id) REFERENCES Admin (admin_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT chk_product_name CHECK (CHAR_LENGTH(TRIM(name)) >= 2),
  INDEX idx_product_active (isActive, createdAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='A garment or accessory; sizes and colours live in ProductVariant';

CREATE TABLE ProductCategory (
  product_id   INT NOT NULL,
  category_id  INT NOT NULL,
  CONSTRAINT pk_product_category PRIMARY KEY (product_id, category_id),
  CONSTRAINT fk_pc_product  FOREIGN KEY (product_id)  REFERENCES Product (product_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_pc_category FOREIGN KEY (category_id) REFERENCES Category (category_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  INDEX idx_pc_category (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Many-to-many: a coat is in Women + Outerwear + New in';

CREATE TABLE ProductVariant (
  variant_id     INT            NOT NULL AUTO_INCREMENT,
  product_id     INT            NOT NULL,
  sku            VARCHAR(80)    NOT NULL,
  configuration  VARCHAR(150)   NOT NULL,                            -- the size label: "M", "EU 40", "W30 L32", "One size"
  color          VARCHAR(50)    NOT NULL,
  price          DECIMAL(10,2)  NOT NULL,
  color_hex      CHAR(7)        NULL,                                -- [added] swatch colour
  sortOrder      SMALLINT       NOT NULL DEFAULT 0,                  -- [added] size order (XS before S before M)
  isActive       BOOLEAN        NOT NULL DEFAULT TRUE,               -- [added] retire one size without losing history
  CONSTRAINT pk_product_variant PRIMARY KEY (variant_id),
  CONSTRAINT uq_variant_sku UNIQUE (sku),
  CONSTRAINT uq_variant_option UNIQUE (product_id, configuration, color),
  CONSTRAINT fk_variant_product FOREIGN KEY (product_id) REFERENCES Product (product_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT chk_variant_price CHECK (price > 0 AND price < 100000),
  CONSTRAINT chk_variant_hex CHECK (color_hex IS NULL OR color_hex REGEXP '^#[0-9A-Fa-f]{6}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='The thing actually sold and stocked: one size in one colour';

CREATE TABLE ProductSpecification (
  specification_id  INT           NOT NULL AUTO_INCREMENT,
  variant_id        INT           NOT NULL,
  spec_name         VARCHAR(80)   NOT NULL,
  spec_value        VARCHAR(150)  NOT NULL,
  unit              VARCHAR(30)   NULL,
  CONSTRAINT pk_product_specification PRIMARY KEY (specification_id),
  CONSTRAINT uq_spec_name UNIQUE (variant_id, spec_name),
  CONSTRAINT fk_spec_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Fabric, care and size-specific measurements (chest width differs per size)';

CREATE TABLE CompatibilityRule (
  rule_id             INT          NOT NULL AUTO_INCREMENT,
  source_variant_id   INT          NOT NULL,
  target_variant_id   INT          NOT NULL,
  compatibility_type  VARCHAR(30)  NOT NULL,
  CONSTRAINT pk_compatibility_rule PRIMARY KEY (rule_id),
  CONSTRAINT uq_compatibility_pair UNIQUE (source_variant_id, target_variant_id),
  CONSTRAINT fk_rule_source FOREIGN KEY (source_variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_rule_target FOREIGN KEY (target_variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT chk_rule_not_self CHECK (source_variant_id <> target_variant_id),
  CONSTRAINT chk_rule_type CHECK (compatibility_type IN ('PAIRS_WITH', 'LAYERS_WITH', 'COMPLETES_LOOK'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='"Style it with": colour-specific outfit pairings';

-- [added] table 31 — not in the diagram (docs/DECISIONS.md, 2026-11-09).
-- Product pictures are stored in the database itself, as binary data (BLOB),
-- so one SQL import or one backup carries the whole shop, pictures included.
--   * A picture belongs to a product and, usually, to one of its colours.
--     A colour comes in 4–6 sizes; keeping the picture per colour, not per
--     ProductVariant row, stores each picture once. A NULL colour means the
--     picture shows every colour (for example a close-up of the fabric).
--   * byte_size and sha256 are generated by the database from the data, so
--     they can never disagree with it. The UNIQUE sha256 refuses the same file
--     twice and is the picture's web address (/api/images/{sha256}): that
--     address never changes meaning, so browsers may cache it for good.
--   * chk_image_bytes keeps every picture under 512 KB, below XAMPP's 1 MB
--     max_allowed_packet. The PHP API resizes and re-encodes uploads first.
CREATE TABLE ProductImage (
  image_id     INT           NOT NULL AUTO_INCREMENT,
  product_id   INT           NOT NULL,
  color        VARCHAR(50)   NULL,                                   -- a ProductVariant.color of the product; NULL = every colour
  sortOrder    SMALLINT      NOT NULL DEFAULT 0,                     -- 0 = the main picture of that colour
  mime_type    VARCHAR(20)   NOT NULL,
  width        SMALLINT      NOT NULL,                               -- pixels (for SVG, the drawing's own size)
  height       SMALLINT      NOT NULL,
  alt_text     VARCHAR(160)  NOT NULL,                               -- read out by screen readers
  credit       VARCHAR(255)  NULL,                                   -- where the picture comes from (photographer, licence)
  data         MEDIUMBLOB    NOT NULL,                               -- the file itself
  byte_size    INT           AS (OCTET_LENGTH(data)) STORED,
  sha256       CHAR(64)      AS (SHA2(data, 256)) STORED,
  uploadedBy   INT           NULL,                                   -- NULL for the sample pictures loaded with the seed
  createdAt    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_product_image PRIMARY KEY (image_id),
  CONSTRAINT uq_image_sha UNIQUE (sha256),
  CONSTRAINT fk_image_product FOREIGN KEY (product_id) REFERENCES Product (product_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_image_admin FOREIGN KEY (uploadedBy) REFERENCES Admin (admin_id)
    ON UPDATE CASCADE ON DELETE SET NULL,
  CONSTRAINT chk_image_mime CHECK (mime_type IN ('image/jpeg', 'image/png', 'image/svg+xml')),
  CONSTRAINT chk_image_bytes CHECK (OCTET_LENGTH(data) BETWEEN 1 AND 524288),
  CONSTRAINT chk_image_size CHECK (width BETWEEN 1 AND 4000 AND height BETWEEN 1 AND 4000),
  CONSTRAINT chk_image_order CHECK (sortOrder >= 0),
  CONSTRAINT chk_image_alt CHECK (CHAR_LENGTH(TRIM(alt_text)) >= 3),
  INDEX idx_image_lookup (product_id, color, sortOrder)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Product pictures stored as binary data, one per colour or for every colour';

-- -----------------------------------------------------------------------------
-- ORDERS
-- -----------------------------------------------------------------------------

CREATE TABLE Cart (
  cart_id             INT          NOT NULL AUTO_INCREMENT,
  customer_id         INT          NOT NULL,
  status              VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
  createdAt           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,                              -- [added]
  updatedAt           DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,  -- [added]
  -- [added] generated helper: equals customer_id only while the cart is ACTIVE,
  -- so the UNIQUE index below allows any number of old carts but one active cart.
  active_customer_id  INT AS (CASE WHEN status = 'ACTIVE' THEN customer_id END) STORED,
  CONSTRAINT pk_cart PRIMARY KEY (cart_id),
  CONSTRAINT uq_cart_one_active UNIQUE (active_customer_id),
  CONSTRAINT fk_cart_customer FOREIGN KEY (customer_id) REFERENCES Customer (customer_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_cart_status CHECK (status IN ('ACTIVE', 'CHECKED_OUT', 'ABANDONED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='A shopping bag; at most one ACTIVE per customer';

CREATE TABLE CartItem (
  cart_item_id  INT            NOT NULL AUTO_INCREMENT,
  cart_id       INT            NOT NULL,
  variant_id    INT            NOT NULL,
  quantity      INT            NOT NULL,
  unit_price    DECIMAL(10,2)  NOT NULL,
  addedAt       DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,   -- [added]
  CONSTRAINT pk_cart_item PRIMARY KEY (cart_item_id),
  CONSTRAINT uq_cart_variant UNIQUE (cart_id, variant_id),
  CONSTRAINT fk_cartitem_cart FOREIGN KEY (cart_id) REFERENCES Cart (cart_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_cartitem_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT chk_cartitem_quantity CHECK (quantity BETWEEN 1 AND 10),
  CONSTRAINT chk_cartitem_price CHECK (unit_price >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- `Order` in the diagram. Renamed because ORDER is reserved in SQL.
CREATE TABLE CustomerOrder (
  order_id        INT            NOT NULL AUTO_INCREMENT,
  customer_id     INT            NOT NULL,
  orderNumber     VARCHAR(50)    NOT NULL,
  status          VARCHAR(30)    NOT NULL DEFAULT 'PLACED',
  totalAmount     DECIMAL(10,2)  NOT NULL,
  placedAt        DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deliveryMethod  VARCHAR(20)    NOT NULL DEFAULT 'STANDARD',        -- [added] flowchart: "choose delivery option"
  shippingFee     DECIMAL(10,2)  NOT NULL DEFAULT 0.00,              -- [added] part of totalAmount
  shipRecipient   VARCHAR(100)   NOT NULL,                           -- [added] immutable shipping snapshot …
  shipLine1       VARCHAR(150)   NOT NULL,                           -- [added]
  shipCity        VARCHAR(80)    NOT NULL,                           -- [added]
  shipRegion      VARCHAR(80)    NOT NULL,                           -- [added]
  shipPostalCode  VARCHAR(20)    NOT NULL,                           -- [added]
  shipCountry     CHAR(2)        NOT NULL DEFAULT 'US',              -- [added] ISO 3166-1 alpha-2
  CONSTRAINT pk_customer_order PRIMARY KEY (order_id),
  CONSTRAINT uq_order_number UNIQUE (orderNumber),
  -- Lets ReturnRequest prove (order, customer) belong together with a composite FK.
  CONSTRAINT uq_order_customer UNIQUE (order_id, customer_id),
  CONSTRAINT fk_order_customer FOREIGN KEY (customer_id) REFERENCES Customer (customer_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_order_status CHECK (status IN ('PLACED', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED')),
  CONSTRAINT chk_order_total CHECK (totalAmount >= 0),
  CONSTRAINT chk_order_fee CHECK (shippingFee >= 0 AND shippingFee <= totalAmount),
  CONSTRAINT chk_order_delivery CHECK (deliveryMethod IN ('STANDARD', 'EXPRESS')),
  CONSTRAINT chk_order_country CHECK (shipCountry REGEXP '^[A-Z]{2}$'),
  INDEX idx_order_placed (placedAt),
  INDEX idx_order_status (status, placedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Diagram table "Order"';

CREATE TABLE OrderItem (
  order_item_id  INT            NOT NULL AUTO_INCREMENT,
  order_id       INT            NOT NULL,
  variant_id     INT            NOT NULL,
  quantity       INT            NOT NULL,
  unitPrice      DECIMAL(10,2)  NOT NULL,                            -- historical price, never recalculated
  CONSTRAINT pk_order_item PRIMARY KEY (order_item_id),
  CONSTRAINT uq_order_variant UNIQUE (order_id, variant_id),
  CONSTRAINT fk_orderitem_order FOREIGN KEY (order_id) REFERENCES CustomerOrder (order_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_orderitem_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_orderitem_quantity CHECK (quantity BETWEEN 1 AND 10),
  CONSTRAINT chk_orderitem_price CHECK (unitPrice >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -----------------------------------------------------------------------------
-- INVENTORY
-- -----------------------------------------------------------------------------

CREATE TABLE Warehouse (
  warehouse_id  INT           NOT NULL AUTO_INCREMENT,
  name          VARCHAR(80)   NOT NULL,
  location      VARCHAR(200)  NOT NULL,
  capacity      INT           NOT NULL,                              -- unit: garments/pairs on hand
  CONSTRAINT pk_warehouse PRIMARY KEY (warehouse_id),
  CONSTRAINT uq_warehouse_name UNIQUE (name),
  CONSTRAINT chk_warehouse_capacity CHECK (capacity > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE Inventory (
  warehouse_id       INT       NOT NULL,
  variant_id         INT       NOT NULL,
  quantity_on_hand   INT       NOT NULL DEFAULT 0,
  quantity_reserved  INT       NOT NULL DEFAULT 0,
  reorder_level      INT       NOT NULL DEFAULT 4,                   -- [added] low-stock threshold
  updatedAt          DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,  -- [added]
  CONSTRAINT pk_inventory PRIMARY KEY (warehouse_id, variant_id),
  CONSTRAINT fk_inventory_warehouse FOREIGN KEY (warehouse_id) REFERENCES Warehouse (warehouse_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_inventory_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  -- The core stock invariant: 0 <= reserved <= on hand.
  CONSTRAINT chk_inventory_balance CHECK (quantity_on_hand >= 0 AND quantity_reserved >= 0
                                          AND quantity_reserved <= quantity_on_hand),
  CONSTRAINT chk_inventory_reorder CHECK (reorder_level >= 0),
  INDEX idx_inventory_variant (variant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Balance per warehouse; on hand changes only through StockMovement (trigger)';

CREATE TABLE StockMovement (
  movement_id      INT          NOT NULL AUTO_INCREMENT,
  warehouse_id     INT          NOT NULL,
  variant_id       INT          NOT NULL,
  quantity_change  INT          NOT NULL,
  reason           VARCHAR(80)  NOT NULL,
  movedAt          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  reference        VARCHAR(50)  NULL,                                -- [added] source document, e.g. PO-1004, ME-10057
  CONSTRAINT pk_stock_movement PRIMARY KEY (movement_id),
  CONSTRAINT fk_movement_warehouse FOREIGN KEY (warehouse_id) REFERENCES Warehouse (warehouse_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_movement_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_movement_nonzero CHECK (quantity_change <> 0),
  CONSTRAINT chk_movement_reason CHECK (reason IN ('OPENING_BALANCE', 'PURCHASE_RECEIPT', 'SALE_SHIPMENT',
                                                   'RETURN_RESTOCK', 'ADJUSTMENT', 'DAMAGE_WRITE_OFF')),
  -- Direction must match the reason (receipts add, shipments remove).
  CONSTRAINT chk_movement_direction CHECK (
       (reason IN ('OPENING_BALANCE', 'PURCHASE_RECEIPT', 'RETURN_RESTOCK') AND quantity_change > 0)
    OR (reason IN ('SALE_SHIPMENT', 'DAMAGE_WRITE_OFF') AND quantity_change < 0)
    OR  reason = 'ADJUSTMENT'),
  INDEX idx_movement_time (movedAt),
  INDEX idx_movement_item (variant_id, warehouse_id, movedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Append-only stock ledger';

-- -----------------------------------------------------------------------------
-- PROCUREMENT
-- -----------------------------------------------------------------------------

CREATE TABLE Supplier (
  supplier_id  INT           NOT NULL AUTO_INCREMENT,
  name         VARCHAR(100)  NOT NULL,
  contact      VARCHAR(100)  NOT NULL,
  CONSTRAINT pk_supplier PRIMARY KEY (supplier_id),
  CONSTRAINT uq_supplier_name UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE SupplierProduct (
  supplier_id        INT            NOT NULL,
  variant_id         INT            NOT NULL,
  unit_cost          DECIMAL(10,2)  NOT NULL,
  lead_time_days     INT            NOT NULL,
  minimum_order_qty  INT            NOT NULL DEFAULT 1,
  CONSTRAINT pk_supplier_product PRIMARY KEY (supplier_id, variant_id),
  CONSTRAINT fk_sp_supplier FOREIGN KEY (supplier_id) REFERENCES Supplier (supplier_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT fk_sp_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT chk_sp_cost CHECK (unit_cost > 0),
  CONSTRAINT chk_sp_lead CHECK (lead_time_days BETWEEN 1 AND 180),
  CONSTRAINT chk_sp_moq CHECK (minimum_order_qty BETWEEN 1 AND 1000),
  INDEX idx_sp_variant (variant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Supplier price list: which supplier can replenish which variant';

CREATE TABLE PurchaseOrder (
  purchase_order_id  INT          NOT NULL AUTO_INCREMENT,
  supplier_id        INT          NOT NULL,
  warehouse_id       INT          NOT NULL,
  status             VARCHAR(30)  NOT NULL DEFAULT 'ORDERED',
  orderedAt          DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  receivedAt         DATETIME     NULL,                              -- [added] idempotent receipt + real lead time
  CONSTRAINT pk_purchase_order PRIMARY KEY (purchase_order_id),
  CONSTRAINT fk_po_supplier FOREIGN KEY (supplier_id) REFERENCES Supplier (supplier_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_po_warehouse FOREIGN KEY (warehouse_id) REFERENCES Warehouse (warehouse_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_po_status CHECK (status IN ('ORDERED', 'RECEIVED', 'CANCELLED')),
  CONSTRAINT chk_po_received CHECK ((status = 'RECEIVED') = (receivedAt IS NOT NULL)),
  CONSTRAINT chk_po_dates CHECK (receivedAt IS NULL OR receivedAt >= orderedAt),
  INDEX idx_po_status (status, orderedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE PurchaseOrderItem (
  po_item_id         INT            NOT NULL AUTO_INCREMENT,
  purchase_order_id  INT            NOT NULL,
  variant_id         INT            NOT NULL,
  quantity           INT            NOT NULL,
  unit_cost          DECIMAL(10,2)  NOT NULL,
  CONSTRAINT pk_purchase_order_item PRIMARY KEY (po_item_id),
  CONSTRAINT uq_po_variant UNIQUE (purchase_order_id, variant_id),
  CONSTRAINT fk_poi_po FOREIGN KEY (purchase_order_id) REFERENCES PurchaseOrder (purchase_order_id)
    ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT fk_poi_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_poi_quantity CHECK (quantity BETWEEN 1 AND 5000),
  CONSTRAINT chk_poi_cost CHECK (unit_cost > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -----------------------------------------------------------------------------
-- FINANCE  (simulated: no card data is ever stored)
-- -----------------------------------------------------------------------------

CREATE TABLE Payment (
  payment_id  INT            NOT NULL AUTO_INCREMENT,
  order_id    INT            NOT NULL,
  amount      DECIMAL(10,2)  NOT NULL,
  status      VARCHAR(30)    NOT NULL,
  method      VARCHAR(30)    NOT NULL DEFAULT 'CARD',                -- [added] simulated method label only
  createdAt   DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,     -- [added]
  CONSTRAINT pk_payment PRIMARY KEY (payment_id),
  CONSTRAINT fk_payment_order FOREIGN KEY (order_id) REFERENCES CustomerOrder (order_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_payment_amount CHECK (amount > 0),
  CONSTRAINT chk_payment_status CHECK (status IN ('PENDING', 'CAPTURED', 'FAILED', 'PARTIALLY_REFUNDED', 'REFUNDED')),
  CONSTRAINT chk_payment_method CHECK (method IN ('CARD', 'PAYPAL', 'APPLE_PAY'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `Transaction` (
  transaction_id   INT            NOT NULL AUTO_INCREMENT,
  payment_id       INT            NOT NULL,
  transactionType  VARCHAR(30)    NOT NULL,
  amount           DECIMAL(10,2)  NOT NULL,
  status           VARCHAR(30)    NOT NULL,
  reference        VARCHAR(40)    NOT NULL,                          -- [added] simulated gateway id; UNIQUE = idempotency
  createdAt        DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP, -- [added]
  CONSTRAINT pk_transaction PRIMARY KEY (transaction_id),
  CONSTRAINT uq_transaction_reference UNIQUE (reference),
  CONSTRAINT fk_transaction_payment FOREIGN KEY (payment_id) REFERENCES Payment (payment_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_transaction_type CHECK (transactionType IN ('CAPTURE', 'REFUND')),
  CONSTRAINT chk_transaction_amount CHECK (amount > 0),
  CONSTRAINT chk_transaction_status CHECK (status IN ('PENDING', 'SUCCESS', 'FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Money movements against a payment: one capture, zero or more refunds';

-- -----------------------------------------------------------------------------
-- FULFILLMENT
-- -----------------------------------------------------------------------------

CREATE TABLE Fulfillment (
  fulfillment_id  INT          NOT NULL AUTO_INCREMENT,
  order_id        INT          NOT NULL,
  admin_id        INT          NULL,                                 -- nullable: assigned when staff start packing
  status          VARCHAR(30)  NOT NULL DEFAULT 'PENDING',
  createdAt       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,   -- [added]
  CONSTRAINT pk_fulfillment PRIMARY KEY (fulfillment_id),
  CONSTRAINT uq_fulfillment_order UNIQUE (order_id),                 -- one fulfillment per order; shipments may split it
  CONSTRAINT fk_fulfillment_order FOREIGN KEY (order_id) REFERENCES CustomerOrder (order_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_fulfillment_admin FOREIGN KEY (admin_id) REFERENCES Admin (admin_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT chk_fulfillment_status CHECK (status IN ('PENDING', 'PROCESSING', 'SHIPPED', 'COMPLETED', 'CANCELLED')),
  CONSTRAINT chk_fulfillment_admin CHECK (status IN ('PENDING', 'CANCELLED') OR admin_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE Shipment (
  shipment_id     INT           NOT NULL AUTO_INCREMENT,
  fulfillment_id  INT           NOT NULL,
  trackingNumber  VARCHAR(100)  NOT NULL,
  status          VARCHAR(30)   NOT NULL DEFAULT 'IN_TRANSIT',
  carrier         VARCHAR(40)   NOT NULL DEFAULT 'UPS',             -- [added]
  shippedAt       DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP, -- [added]
  deliveredAt     DATETIME      NULL,                               -- [added] starts the return window
  CONSTRAINT pk_shipment PRIMARY KEY (shipment_id),
  CONSTRAINT uq_shipment_tracking UNIQUE (trackingNumber),
  CONSTRAINT fk_shipment_fulfillment FOREIGN KEY (fulfillment_id) REFERENCES Fulfillment (fulfillment_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_shipment_status CHECK (status IN ('IN_TRANSIT', 'DELIVERED')),
  CONSTRAINT chk_shipment_delivered CHECK ((status = 'DELIVERED') = (deliveredAt IS NOT NULL)),
  CONSTRAINT chk_shipment_dates CHECK (deliveredAt IS NULL OR deliveredAt >= shippedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='One parcel; an order shipped from two warehouses has two shipments';

CREATE TABLE OrderAllocation (
  allocation_id   INT          NOT NULL AUTO_INCREMENT,
  order_item_id   INT          NOT NULL,
  warehouse_id    INT          NOT NULL,
  fulfillment_id  INT          NOT NULL,
  shipment_id     INT          NULL,
  allocated_qty   INT          NOT NULL,
  status          VARCHAR(20)  NOT NULL DEFAULT 'RESERVED',          -- [added] RESERVED → SHIPPED, or RELEASED
  CONSTRAINT pk_order_allocation PRIMARY KEY (allocation_id),
  CONSTRAINT uq_allocation_item_wh UNIQUE (order_item_id, warehouse_id),
  CONSTRAINT fk_alloc_item FOREIGN KEY (order_item_id) REFERENCES OrderItem (order_item_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_alloc_warehouse FOREIGN KEY (warehouse_id) REFERENCES Warehouse (warehouse_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_alloc_fulfillment FOREIGN KEY (fulfillment_id) REFERENCES Fulfillment (fulfillment_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_alloc_shipment FOREIGN KEY (shipment_id) REFERENCES Shipment (shipment_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_alloc_qty CHECK (allocated_qty > 0),
  CONSTRAINT chk_alloc_status CHECK (status IN ('RESERVED', 'SHIPPED', 'RELEASED')),
  CONSTRAINT chk_alloc_shipment CHECK ((status = 'SHIPPED') = (shipment_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Which warehouse supplies how many units of an order line';

CREATE TABLE OrderCancellation (
  cancellation_id  INT           NOT NULL AUTO_INCREMENT,
  order_id         INT           NOT NULL,
  cancelledBy      INT           NULL,                              -- Admin who cancelled; NULL when the customer did
  reason           VARCHAR(255)  NOT NULL,
  cancelledAt      DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  initiatedBy      VARCHAR(10)   NOT NULL,                          -- [added] CUSTOMER or ADMIN
  CONSTRAINT pk_order_cancellation PRIMARY KEY (cancellation_id),
  CONSTRAINT uq_cancellation_order UNIQUE (order_id),               -- diagram: an order MAY HAVE 0..1 cancellation
  CONSTRAINT fk_cancel_order FOREIGN KEY (order_id) REFERENCES CustomerOrder (order_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_cancel_admin FOREIGN KEY (cancelledBy) REFERENCES Admin (admin_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT chk_cancel_actor CHECK ((initiatedBy = 'ADMIN' AND cancelledBy IS NOT NULL)
                                  OR (initiatedBy = 'CUSTOMER' AND cancelledBy IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -----------------------------------------------------------------------------
-- AFTER-SALES
-- -----------------------------------------------------------------------------

CREATE TABLE ReturnRequest (
  return_request_id  INT           NOT NULL AUTO_INCREMENT,
  order_id           INT           NOT NULL,
  customer_id        INT           NOT NULL,
  status             VARCHAR(30)   NOT NULL DEFAULT 'REQUESTED',
  reason             VARCHAR(255)  NOT NULL,                        -- [added] "too small", "colour not as pictured"
  requestedAt        DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- [added]
  resolvedAt         DATETIME      NULL,                            -- [added]
  CONSTRAINT pk_return_request PRIMARY KEY (return_request_id),
  -- Composite FK: the customer on the return must be the customer on the order.
  CONSTRAINT fk_return_order_customer FOREIGN KEY (order_id, customer_id)
    REFERENCES CustomerOrder (order_id, customer_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_return_customer FOREIGN KEY (customer_id) REFERENCES Customer (customer_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_return_status CHECK (status IN ('REQUESTED', 'APPROVED', 'REJECTED', 'REFUNDED')),
  CONSTRAINT chk_return_resolved CHECK (resolvedAt IS NULL OR resolvedAt >= requestedAt),
  INDEX idx_return_status (status, requestedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE ReturnItem (
  return_item_id     INT NOT NULL AUTO_INCREMENT,
  return_request_id  INT NOT NULL,
  order_item_id      INT NOT NULL,
  quantity           INT NOT NULL,
  CONSTRAINT pk_return_item PRIMARY KEY (return_item_id),
  CONSTRAINT uq_return_line UNIQUE (return_request_id, order_item_id),
  CONSTRAINT fk_returnitem_request FOREIGN KEY (return_request_id) REFERENCES ReturnRequest (return_request_id)
    ON UPDATE RESTRICT ON DELETE CASCADE,
  CONSTRAINT fk_returnitem_orderitem FOREIGN KEY (order_item_id) REFERENCES OrderItem (order_item_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_returnitem_quantity CHECK (quantity > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE Refund (
  refund_id       INT            NOT NULL AUTO_INCREMENT,
  return_item_id  INT            NOT NULL,
  transaction_id  INT            NULL,
  amount          DECIMAL(10,2)  NOT NULL,
  status          VARCHAR(30)    NOT NULL DEFAULT 'PENDING',
  createdAt       DATETIME       NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- [added]
  CONSTRAINT pk_refund PRIMARY KEY (refund_id),
  CONSTRAINT uq_refund_transaction UNIQUE (transaction_id),          -- a transaction documents at most one refund
  CONSTRAINT fk_refund_returnitem FOREIGN KEY (return_item_id) REFERENCES ReturnItem (return_item_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_refund_transaction FOREIGN KEY (transaction_id) REFERENCES `Transaction` (transaction_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_refund_amount CHECK (amount > 0),
  CONSTRAINT chk_refund_status CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED')),
  CONSTRAINT chk_refund_completed CHECK (status <> 'COMPLETED' OR transaction_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE Warranty (
  warranty_id      INT   NOT NULL AUTO_INCREMENT,
  variant_id       INT   NOT NULL,
  duration_months  INT   NOT NULL,
  coverage         TEXT  NOT NULL,
  CONSTRAINT pk_warranty PRIMARY KEY (warranty_id),
  CONSTRAINT fk_warranty_variant FOREIGN KEY (variant_id) REFERENCES ProductVariant (variant_id)
    ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT chk_warranty_duration CHECK (duration_months BETWEEN 1 AND 60),
  INDEX idx_warranty_variant (variant_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
  COMMENT='Quality guarantee: seams, stitching, soles, zips';

CREATE TABLE WarrantyClaim (
  claim_id       INT           NOT NULL AUTO_INCREMENT,
  warranty_id    INT           NOT NULL,
  order_item_id  INT           NOT NULL,
  reason         VARCHAR(255)  NOT NULL,
  status         VARCHAR(30)   NOT NULL DEFAULT 'SUBMITTED',
  submittedAt    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- [added] eligibility is judged at this moment
  resolution     VARCHAR(255)  NULL,                                -- [added] "Replacement sent", "Repaired"
  resolvedAt     DATETIME      NULL,                                -- [added]
  CONSTRAINT pk_warranty_claim PRIMARY KEY (claim_id),
  CONSTRAINT fk_claim_warranty FOREIGN KEY (warranty_id) REFERENCES Warranty (warranty_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_claim_orderitem FOREIGN KEY (order_item_id) REFERENCES OrderItem (order_item_id)
    ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_claim_status CHECK (status IN ('SUBMITTED', 'APPROVED', 'REJECTED', 'RESOLVED')),
  CONSTRAINT chk_claim_resolution CHECK (status NOT IN ('REJECTED', 'RESOLVED')
                                         OR (resolution IS NOT NULL AND resolvedAt IS NOT NULL)),
  INDEX idx_claim_status (status, submittedAt)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- >>> 02_functions.sql
-- =============================================================================
-- MyEnterprise — File 02: stored functions
-- -----------------------------------------------------------------------------
-- Small, reusable calculations. Procedures, triggers, views, the business
-- queries and the PHP API all call these, so a rule is written once.
--
-- Every lookup here uses an aggregate (SUM/MAX/COALESCE), which always returns
-- exactly one row. A plain SELECT … INTO that finds nothing raises a NOT FOUND
-- condition, and that condition could stop a caller's cursor loop early.
-- (F6 uses scalar subqueries, which return NULL instead of raising it.)
--
-- phpMyAdmin: import this file as-is; it contains DELIMITER statements.
-- =============================================================================

USE myenterprise;

DROP FUNCTION IF EXISTS fn_available_stock;
DROP FUNCTION IF EXISTS fn_returnable_quantity;
DROP FUNCTION IF EXISTS fn_refundable_amount;
DROP FUNCTION IF EXISTS fn_warranty_expires_on;
DROP FUNCTION IF EXISTS fn_payment_refunded_total;
DROP FUNCTION IF EXISTS fn_product_image;

DELIMITER $$

-- F1. Units of a variant that can still be sold: on hand minus reserved,
--     summed over every warehouse.
CREATE FUNCTION fn_available_stock(p_variant_id INT)
RETURNS INT
NOT DETERMINISTIC
READS SQL DATA
COMMENT 'Sellable units of a variant across all warehouses'
BEGIN
  DECLARE v_available INT;
  SELECT COALESCE(SUM(quantity_on_hand - quantity_reserved), 0)
    INTO v_available
    FROM Inventory
   WHERE variant_id = p_variant_id;
  RETURN v_available;
END$$

-- F2. How many units of an order line can still be returned:
--     purchased quantity minus every non-rejected return of that line.
CREATE FUNCTION fn_returnable_quantity(p_order_item_id INT)
RETURNS INT
NOT DETERMINISTIC
READS SQL DATA
COMMENT 'Purchased units minus units already on a non-rejected return'
BEGIN
  DECLARE v_purchased INT;
  DECLARE v_returned  INT;

  SELECT COALESCE(MAX(quantity), 0) INTO v_purchased
    FROM OrderItem
   WHERE order_item_id = p_order_item_id;

  SELECT COALESCE(SUM(ri.quantity), 0) INTO v_returned
    FROM ReturnItem ri
    JOIN ReturnRequest rr ON rr.return_request_id = ri.return_request_id
   WHERE ri.order_item_id = p_order_item_id
     AND rr.status <> 'REJECTED';

  RETURN GREATEST(v_purchased - v_returned, 0);
END$$

-- F3. Money still refundable for one return line:
--     returned units × the historical unit price, minus refunds already
--     issued (pending or completed) for that line.
CREATE FUNCTION fn_refundable_amount(p_return_item_id INT)
RETURNS DECIMAL(10,2)
NOT DETERMINISTIC
READS SQL DATA
COMMENT 'Returned quantity x historical price, less refunds already issued'
BEGIN
  DECLARE v_value    DECIMAL(10,2);
  DECLARE v_refunded DECIMAL(10,2);

  SELECT COALESCE(MAX(ri.quantity * oi.unitPrice), 0) INTO v_value
    FROM ReturnItem ri
    JOIN OrderItem oi ON oi.order_item_id = ri.order_item_id
   WHERE ri.return_item_id = p_return_item_id;

  SELECT COALESCE(SUM(amount), 0) INTO v_refunded
    FROM Refund
   WHERE return_item_id = p_return_item_id
     AND status <> 'FAILED';

  RETURN GREATEST(v_value - v_refunded, 0);
END$$

-- F4. Last day a quality guarantee covers an order line.
--     Coverage starts when the parcel holding the item is delivered,
--     and lasts duration_months. NULL = not delivered yet (no coverage).
CREATE FUNCTION fn_warranty_expires_on(p_order_item_id INT, p_warranty_id INT)
RETURNS DATE
NOT DETERMINISTIC
READS SQL DATA
COMMENT 'Delivery date + warranty duration; NULL until the item is delivered'
BEGIN
  DECLARE v_delivered DATETIME;
  DECLARE v_months    INT;

  SELECT MAX(s.deliveredAt) INTO v_delivered
    FROM OrderAllocation oa
    JOIN Shipment s ON s.shipment_id = oa.shipment_id
   WHERE oa.order_item_id = p_order_item_id
     AND s.status = 'DELIVERED';

  SELECT MAX(duration_months) INTO v_months
    FROM Warranty
   WHERE warranty_id = p_warranty_id;

  IF v_delivered IS NULL OR v_months IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN DATE(v_delivered + INTERVAL v_months MONTH);
END$$

-- F5. Total successfully refunded against one payment
--     (return refunds and cancellation refunds alike).
CREATE FUNCTION fn_payment_refunded_total(p_payment_id INT)
RETURNS DECIMAL(10,2)
NOT DETERMINISTIC
READS SQL DATA
COMMENT 'Sum of successful REFUND transactions for a payment'
BEGIN
  DECLARE v_total DECIMAL(10,2);
  SELECT COALESCE(SUM(amount), 0) INTO v_total
    FROM `Transaction`
   WHERE payment_id = p_payment_id
     AND transactionType = 'REFUND'
     AND status = 'SUCCESS';
  RETURN v_total;
END$$

-- F6. Which picture to show for a product in one colour: that colour's main
--     picture, otherwise a picture made for every colour (color IS NULL).
--     With p_color NULL it answers for the product as a whole: its first
--     colour, falling back to any picture of the product.
--     Returns the picture's key (its SHA-256), which is also its web address,
--     /api/images/{key}. NULL means the product has no picture yet.
CREATE FUNCTION fn_product_image(p_product_id INT, p_color VARCHAR(50))
RETURNS CHAR(64)
NOT DETERMINISTIC
READS SQL DATA
COMMENT 'Key (SHA-256) of the main picture for a product colour; NULL if none'
BEGIN
  DECLARE v_color VARCHAR(50) DEFAULT p_color;
  IF v_color IS NULL THEN
    SET v_color = (SELECT color FROM ProductVariant
                    WHERE product_id = p_product_id
                    ORDER BY isActive DESC, sortOrder, variant_id
                    LIMIT 1);
  END IF;
  RETURN (SELECT sha256 FROM ProductImage
           WHERE product_id = p_product_id
             AND (color <=> v_color OR color IS NULL OR p_color IS NULL)
           ORDER BY (color <=> v_color) DESC, (color IS NULL) DESC, sortOrder, image_id
           LIMIT 1);
END$$

DELIMITER ;


-- >>> 03_procedures.sql
-- =============================================================================
-- MyEnterprise — File 03: stored procedures (with the three required cursors)
-- -----------------------------------------------------------------------------
--   P1 sp_checkout_cart           CURSOR 1  cart lines → order, stock reservation, payment
--   P2 sp_receive_purchase_order  CURSOR 2  PO lines   → stock ledger (trigger T1 adds stock)
--   P3 sp_cancel_order            CURSOR 3  allocations → reservations released, refund
--   P4 sp_ship_order              CURSOR 4  warehouses → one parcel per warehouse
--   P5 sp_start_fulfillment                 PLACED → PROCESSING, assigns the packer
--   P6 sp_complete_return                   approved return → restock + refunds
--
-- Every procedure owns its transaction:
--   START TRANSACTION … COMMIT, and an EXIT HANDLER that rolls back and
--   re-raises the original error, so a failure leaves no partial data.
-- Business-rule failures use SIGNAL SQLSTATE '45000' with a sentence the shop
-- can show to people as-is. The PHP API calls these procedures; it does not
-- wrap them in a transaction of its own.
--
-- Cursor loops are written in a nested BEGIN … END block that owns the
-- NOT FOUND handler, so a lookup elsewhere cannot end a loop early.
-- =============================================================================

USE myenterprise;

DROP PROCEDURE IF EXISTS sp_checkout_cart;
DROP PROCEDURE IF EXISTS sp_receive_purchase_order;
DROP PROCEDURE IF EXISTS sp_cancel_order;
DROP PROCEDURE IF EXISTS sp_ship_order;
DROP PROCEDURE IF EXISTS sp_start_fulfillment;
DROP PROCEDURE IF EXISTS sp_complete_return;

DELIMITER $$

-- -----------------------------------------------------------------------------
-- P1 · sp_checkout_cart — CURSOR 1
-- Turns the customer's ACTIVE cart into a paid order in one transaction:
--   1. locks the cart (a double-click cannot check out twice);
--   2. CURSOR over cart lines in variant order (every checkout locks stock
--      rows in the same order, so two checkouts cannot deadlock);
--   3. per line: checks the item is still sold, locks its stock rows, checks
--      availability, writes the OrderItem at today's price, then reserves
--      stock per warehouse — preferring a warehouse already used by this
--      order, then one that can supply the whole line (fewer parcels);
--   4. sets the delivery fee, simulates the card capture (Payment +
--      Transaction), and closes the cart.
-- Delivery: EXPRESS 18.00; STANDARD free from 150.00, otherwise 6.00.
-- -----------------------------------------------------------------------------
CREATE PROCEDURE sp_checkout_cart(
  IN  p_customer_id      INT,
  IN  p_delivery_method  VARCHAR(20),
  IN  p_payment_method   VARCHAR(30),
  IN  p_recipient        VARCHAR(100),
  IN  p_line1            VARCHAR(150),
  IN  p_city             VARCHAR(80),
  IN  p_region           VARCHAR(80),
  IN  p_postal_code      VARCHAR(20),
  IN  p_country          CHAR(2),
  OUT p_order_id         INT
)
MODIFIES SQL DATA
COMMENT 'Cursor 1: active cart -> order, warehouse reservations and simulated payment'
BEGIN
  DECLARE v_cart_id      INT;
  DECLARE v_fulfillment  INT;
  DECLARE v_payment      INT;
  DECLARE v_subtotal     DECIMAL(10,2) DEFAULT 0;
  DECLARE v_fee          DECIMAL(10,2) DEFAULT 0;
  DECLARE v_lines        INT DEFAULT 0;
  DECLARE v_msg          VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_order_id = NULL;

  IF p_delivery_method IS NULL OR p_delivery_method NOT IN ('STANDARD', 'EXPRESS') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Choose standard or express delivery.';
  END IF;
  IF p_payment_method IS NULL OR p_payment_method NOT IN ('CARD', 'PAYPAL', 'APPLE_PAY') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Choose a payment method.';
  END IF;
  IF COALESCE(TRIM(p_recipient), '') = '' OR COALESCE(TRIM(p_line1), '') = ''
     OR COALESCE(TRIM(p_city), '') = '' OR COALESCE(TRIM(p_region), '') = ''
     OR COALESCE(TRIM(p_postal_code), '') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Complete the delivery address.';
  END IF;

  START TRANSACTION;

  -- 1. Lock the active cart. A second, concurrent checkout waits here and then
  --    finds the cart already CHECKED_OUT.
  SELECT MAX(cart_id) INTO v_cart_id
    FROM Cart
   WHERE customer_id = p_customer_id AND status = 'ACTIVE'
   FOR UPDATE;

  IF v_cart_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Your bag is empty.';
  END IF;

  -- 2. Order header. orderNumber needs the new id, so a unique placeholder is
  --    written first and replaced straight after.
  INSERT INTO CustomerOrder
    (customer_id, orderNumber, status, totalAmount, placedAt, deliveryMethod, shippingFee,
     shipRecipient, shipLine1, shipCity, shipRegion, shipPostalCode, shipCountry)
  VALUES
    (p_customer_id, CONCAT('TMP-', UUID()), 'PLACED', 0, NOW(), p_delivery_method, 0,
     TRIM(p_recipient), TRIM(p_line1), TRIM(p_city), TRIM(p_region), TRIM(p_postal_code),
     UPPER(COALESCE(NULLIF(TRIM(p_country), ''), 'US')));
  SET p_order_id = LAST_INSERT_ID();

  UPDATE CustomerOrder
     SET orderNumber = CONCAT('ME-', 10000 + p_order_id)
   WHERE order_id = p_order_id;

  INSERT INTO Fulfillment (order_id, admin_id, status) VALUES (p_order_id, NULL, 'PENDING');
  SET v_fulfillment = LAST_INSERT_ID();

  -- 3. CURSOR 1 — one pass per cart line.
  cart_lines: BEGIN
    DECLARE v_done        TINYINT DEFAULT 0;
    DECLARE v_variant_id  INT;
    DECLARE v_quantity    INT;
    DECLARE v_price       DECIMAL(10,2);
    DECLARE v_sellable    TINYINT;
    DECLARE v_sku         VARCHAR(80);
    DECLARE v_available   INT;
    DECLARE v_order_item  INT;
    DECLARE v_remaining   INT;
    DECLARE v_wh          INT;
    DECLARE v_take        INT;

    DECLARE cart_cursor CURSOR FOR
      SELECT ci.variant_id, ci.quantity, pv.price, (pv.isActive AND p.isActive), pv.sku
        FROM CartItem ci
        JOIN ProductVariant pv ON pv.variant_id = ci.variant_id
        JOIN Product p        ON p.product_id  = pv.product_id
       WHERE ci.cart_id = v_cart_id
       ORDER BY ci.variant_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN cart_cursor;
    read_line: LOOP
      FETCH cart_cursor INTO v_variant_id, v_quantity, v_price, v_sellable, v_sku;
      IF v_done = 1 THEN
        LEAVE read_line;
      END IF;

      SET v_lines = v_lines + 1;

      IF v_sellable = 0 THEN
        SET v_msg = CONCAT('Item ', v_sku, ' is no longer sold. Remove it from your bag to continue.');
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
      END IF;

      -- Lock every stock row of this variant, then check the total.
      SELECT COALESCE(SUM(quantity_on_hand - quantity_reserved), 0) INTO v_available
        FROM Inventory
       WHERE variant_id = v_variant_id
       FOR UPDATE;

      IF v_available < v_quantity THEN
        SET v_msg = CONCAT('Only ', v_available, ' left of ', v_sku, '. Lower the quantity to continue.');
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
      END IF;

      INSERT INTO OrderItem (order_id, variant_id, quantity, unitPrice)
      VALUES (p_order_id, v_variant_id, v_quantity, v_price);
      SET v_order_item = LAST_INSERT_ID();
      SET v_subtotal   = v_subtotal + v_quantity * v_price;

      -- Reserve the units, splitting across warehouses only when needed.
      SET v_remaining = v_quantity;
      WHILE v_remaining > 0 DO
        SELECT MAX(pick.warehouse_id), MAX(pick.available) INTO v_wh, v_take
          FROM (SELECT i.warehouse_id,
                       i.quantity_on_hand - i.quantity_reserved AS available
                  FROM Inventory i
                 WHERE i.variant_id = v_variant_id
                   AND i.quantity_on_hand - i.quantity_reserved > 0
                 ORDER BY EXISTS (SELECT 1 FROM OrderAllocation oa
                                   WHERE oa.fulfillment_id = v_fulfillment
                                     AND oa.warehouse_id  = i.warehouse_id) DESC,
                          (i.quantity_on_hand - i.quantity_reserved >= v_remaining) DESC,
                          i.quantity_on_hand - i.quantity_reserved DESC,
                          i.warehouse_id
                 LIMIT 1) AS pick;

        IF v_wh IS NULL THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stock changed during checkout. Please try again.';
        END IF;

        SET v_take = LEAST(v_take, v_remaining);

        UPDATE Inventory
           SET quantity_reserved = quantity_reserved + v_take
         WHERE warehouse_id = v_wh AND variant_id = v_variant_id;

        INSERT INTO OrderAllocation (order_item_id, warehouse_id, fulfillment_id, shipment_id, allocated_qty, status)
        VALUES (v_order_item, v_wh, v_fulfillment, NULL, v_take, 'RESERVED');

        SET v_remaining = v_remaining - v_take;
      END WHILE;
    END LOOP read_line;
    CLOSE cart_cursor;
  END cart_lines;

  IF v_lines = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Your bag is empty.';
  END IF;

  -- 4. Totals, simulated payment, close the cart.
  SET v_fee = CASE
                WHEN p_delivery_method = 'EXPRESS' THEN 18.00
                WHEN v_subtotal >= 150.00          THEN 0.00
                ELSE 6.00
              END;

  UPDATE CustomerOrder
     SET totalAmount = v_subtotal + v_fee,
         shippingFee = v_fee
   WHERE order_id = p_order_id;

  INSERT INTO Payment (order_id, amount, status, method)
  VALUES (p_order_id, v_subtotal + v_fee, 'CAPTURED', p_payment_method);
  SET v_payment = LAST_INSERT_ID();

  INSERT INTO `Transaction` (payment_id, transactionType, amount, status, reference)
  VALUES (v_payment, 'CAPTURE', v_subtotal + v_fee, 'SUCCESS', CONCAT('SIM-CAP-', v_payment));

  UPDATE Cart SET status = 'CHECKED_OUT' WHERE cart_id = v_cart_id;

  COMMIT;
END$$


-- -----------------------------------------------------------------------------
-- P2 · sp_receive_purchase_order — CURSOR 2
-- Receives a purchase order in full, exactly once:
--   * locks the PO row; RECEIVED or CANCELLED orders are refused, so a
--     repeated click cannot add the stock twice;
--   * CURSOR over the PO lines writes one PURCHASE_RECEIPT StockMovement per
--     line. Trigger T1 (trg_stock_movement_apply) adds the units to Inventory
--     and enforces warehouse capacity — the procedure never edits Inventory;
--   * marks the PO RECEIVED with the receipt time (used for real lead times).
-- -----------------------------------------------------------------------------
CREATE PROCEDURE sp_receive_purchase_order(
  IN  p_purchase_order_id  INT,
  OUT p_lines_received     INT,
  OUT p_units_received     INT
)
MODIFIES SQL DATA
COMMENT 'Cursor 2: purchase-order lines -> stock ledger; PO marked RECEIVED once'
BEGIN
  DECLARE v_status     VARCHAR(30);
  DECLARE v_warehouse  INT;
  DECLARE v_msg        VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_lines_received = 0;
  SET p_units_received = 0;

  START TRANSACTION;

  SELECT MAX(status), MAX(warehouse_id) INTO v_status, v_warehouse
    FROM PurchaseOrder
   WHERE purchase_order_id = p_purchase_order_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Purchase order not found.';
  ELSEIF v_status = 'RECEIVED' THEN
    SET v_msg = CONCAT('PO-', p_purchase_order_id, ' was already received. Stock was not added again.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  ELSEIF v_status <> 'ORDERED' THEN
    SET v_msg = CONCAT('PO-', p_purchase_order_id, ' is ', LOWER(v_status), ' and cannot be received.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  po_lines: BEGIN
    DECLARE v_done     TINYINT DEFAULT 0;
    DECLARE v_variant  INT;
    DECLARE v_quantity INT;

    DECLARE po_cursor CURSOR FOR
      SELECT variant_id, quantity
        FROM PurchaseOrderItem
       WHERE purchase_order_id = p_purchase_order_id
       ORDER BY variant_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN po_cursor;
    read_line: LOOP
      FETCH po_cursor INTO v_variant, v_quantity;
      IF v_done = 1 THEN
        LEAVE read_line;
      END IF;

      -- Trigger T1 turns this ledger row into an Inventory increase.
      INSERT INTO StockMovement (warehouse_id, variant_id, quantity_change, reason, movedAt, reference)
      VALUES (v_warehouse, v_variant, v_quantity, 'PURCHASE_RECEIPT', NOW(),
              CONCAT('PO-', p_purchase_order_id));

      SET p_lines_received = p_lines_received + 1;
      SET p_units_received = p_units_received + v_quantity;
    END LOOP read_line;
    CLOSE po_cursor;
  END po_lines;

  IF p_lines_received = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This purchase order has no lines to receive.';
  END IF;

  UPDATE PurchaseOrder
     SET status = 'RECEIVED', receivedAt = NOW()
   WHERE purchase_order_id = p_purchase_order_id;

  COMMIT;
END$$


-- -----------------------------------------------------------------------------
-- P3 · sp_cancel_order — CURSOR 3
-- Cancels an order that has not shipped:
--   * customers may cancel while the order is PLACED; staff also while it is
--     PROCESSING (being packed). Shipped orders go through returns instead;
--   * CURSOR over the RESERVED allocations gives each unit back to its
--     warehouse and marks the allocation RELEASED (history is kept);
--   * records the OrderCancellation (0..1 per order, enforced by UNIQUE);
--   * refunds whatever was captured as one simulated REFUND transaction.
-- -----------------------------------------------------------------------------
CREATE PROCEDURE sp_cancel_order(
  IN  p_order_id      INT,
  IN  p_initiated_by  VARCHAR(10),
  IN  p_admin_id      INT,
  IN  p_reason        VARCHAR(255),
  OUT p_units_released INT,
  OUT p_refunded       DECIMAL(10,2)
)
MODIFIES SQL DATA
COMMENT 'Cursor 3: release reserved stock per allocation, record cancellation, refund'
BEGIN
  DECLARE v_status    VARCHAR(30);
  DECLARE v_number    VARCHAR(50);
  DECLARE v_payment   INT;
  DECLARE v_captured  DECIMAL(10,2);
  DECLARE v_msg       VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_units_released = 0;
  SET p_refunded = 0;

  IF p_initiated_by NOT IN ('CUSTOMER', 'ADMIN') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cancellation must be made by the customer or a staff member.';
  END IF;
  IF p_initiated_by = 'ADMIN' AND p_admin_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A staff cancellation needs the staff member.';
  END IF;
  IF COALESCE(TRIM(p_reason), '') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Give a reason for the cancellation.';
  END IF;

  START TRANSACTION;

  SELECT MAX(status), MAX(orderNumber) INTO v_status, v_number
    FROM CustomerOrder
   WHERE order_id = p_order_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order not found.';
  ELSEIF v_status = 'CANCELLED' THEN
    SET v_msg = CONCAT('Order ', v_number, ' is already cancelled.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  ELSEIF v_status IN ('SHIPPED', 'DELIVERED') THEN
    SET v_msg = CONCAT('Order ', v_number, ' has shipped. Start a return once it arrives.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  ELSEIF v_status = 'PROCESSING' AND p_initiated_by = 'CUSTOMER' THEN
    SET v_msg = CONCAT('Order ', v_number, ' is being packed. Contact customer care to cancel it.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  release_stock: BEGIN
    DECLARE v_done       TINYINT DEFAULT 0;
    DECLARE v_allocation INT;
    DECLARE v_warehouse  INT;
    DECLARE v_variant    INT;
    DECLARE v_qty        INT;

    DECLARE alloc_cursor CURSOR FOR
      SELECT oa.allocation_id, oa.warehouse_id, oi.variant_id, oa.allocated_qty
        FROM OrderAllocation oa
        JOIN OrderItem oi ON oi.order_item_id = oa.order_item_id
       WHERE oi.order_id = p_order_id
         AND oa.status = 'RESERVED'
       ORDER BY oi.variant_id, oa.warehouse_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN alloc_cursor;
    read_allocation: LOOP
      FETCH alloc_cursor INTO v_allocation, v_warehouse, v_variant, v_qty;
      IF v_done = 1 THEN
        LEAVE read_allocation;
      END IF;

      UPDATE Inventory
         SET quantity_reserved = quantity_reserved - v_qty
       WHERE warehouse_id = v_warehouse AND variant_id = v_variant;

      UPDATE OrderAllocation
         SET status = 'RELEASED'
       WHERE allocation_id = v_allocation;

      SET p_units_released = p_units_released + v_qty;
    END LOOP read_allocation;
    CLOSE alloc_cursor;
  END release_stock;

  INSERT INTO OrderCancellation (order_id, cancelledBy, reason, cancelledAt, initiatedBy)
  VALUES (p_order_id, IF(p_initiated_by = 'ADMIN', p_admin_id, NULL), TRIM(p_reason), NOW(), p_initiated_by);

  -- Refund everything captured and not yet refunded (simulated).
  SELECT MAX(payment_id) INTO v_payment
    FROM Payment
   WHERE order_id = p_order_id AND status IN ('CAPTURED', 'PARTIALLY_REFUNDED')
   FOR UPDATE;

  IF v_payment IS NOT NULL THEN
    SELECT amount - fn_payment_refunded_total(payment_id) INTO v_captured
      FROM Payment WHERE payment_id = v_payment;

    IF v_captured > 0 THEN
      INSERT INTO `Transaction` (payment_id, transactionType, amount, status, reference)
      VALUES (v_payment, 'REFUND', v_captured, 'SUCCESS', CONCAT('SIM-RFD-C', v_payment));
      SET p_refunded = v_captured;
    END IF;

    UPDATE Payment SET status = 'REFUNDED' WHERE payment_id = v_payment;
  END IF;

  UPDATE Fulfillment SET status = 'CANCELLED' WHERE order_id = p_order_id;
  UPDATE CustomerOrder SET status = 'CANCELLED' WHERE order_id = p_order_id;

  COMMIT;
END$$


-- -----------------------------------------------------------------------------
-- P4 · sp_ship_order — CURSOR 4
-- Ships every reserved unit of an order. CURSOR over the warehouses holding
-- reservations: each warehouse becomes one Shipment (parcel) with its own
-- tracking number. For each parcel the reservation is released and a
-- SALE_SHIPMENT ledger row removes the units (trigger T1 updates on hand),
-- then the allocations point at the parcel.
-- -----------------------------------------------------------------------------
CREATE PROCEDURE sp_ship_order(
  IN  p_order_id   INT,
  IN  p_admin_id   INT,
  IN  p_carrier    VARCHAR(40),
  OUT p_shipments  INT
)
MODIFIES SQL DATA
COMMENT 'Cursor 4: one shipment per warehouse; reservations become stock movements'
BEGIN
  DECLARE v_status       VARCHAR(30);
  DECLARE v_number       VARCHAR(50);
  DECLARE v_fulfillment  INT;
  DECLARE v_msg          VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_shipments = 0;

  IF p_admin_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A staff member must ship the order.';
  END IF;
  IF COALESCE(TRIM(p_carrier), '') = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Choose a carrier.';
  END IF;

  START TRANSACTION;

  SELECT MAX(status), MAX(orderNumber) INTO v_status, v_number
    FROM CustomerOrder
   WHERE order_id = p_order_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order not found.';
  ELSEIF v_status NOT IN ('PLACED', 'PROCESSING') THEN
    SET v_msg = CONCAT('Order ', v_number, ' is ', LOWER(v_status), ' and cannot be shipped.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  SELECT MAX(fulfillment_id) INTO v_fulfillment
    FROM Fulfillment
   WHERE order_id = p_order_id
   FOR UPDATE;

  parcels: BEGIN
    DECLARE v_done      TINYINT DEFAULT 0;
    DECLARE v_warehouse INT;
    DECLARE v_shipment  INT;

    DECLARE warehouse_cursor CURSOR FOR
      SELECT DISTINCT warehouse_id
        FROM OrderAllocation
       WHERE fulfillment_id = v_fulfillment AND status = 'RESERVED'
       ORDER BY warehouse_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN warehouse_cursor;
    read_warehouse: LOOP
      FETCH warehouse_cursor INTO v_warehouse;
      IF v_done = 1 THEN
        LEAVE read_warehouse;
      END IF;

      INSERT INTO Shipment (fulfillment_id, trackingNumber, status, carrier, shippedAt)
      VALUES (v_fulfillment, CONCAT('TMP-', UUID()), 'IN_TRANSIT', TRIM(p_carrier), NOW());
      SET v_shipment = LAST_INSERT_ID();

      UPDATE Shipment
         SET trackingNumber = CONCAT(UPPER(LEFT(TRIM(p_carrier), 3)), '-', LPAD(v_shipment, 9, '0'))
       WHERE shipment_id = v_shipment;

      -- Reservation ends …
      UPDATE Inventory i
        JOIN (SELECT oi.variant_id, SUM(oa.allocated_qty) AS qty
                FROM OrderAllocation oa
                JOIN OrderItem oi ON oi.order_item_id = oa.order_item_id
               WHERE oa.fulfillment_id = v_fulfillment
                 AND oa.warehouse_id   = v_warehouse
                 AND oa.status = 'RESERVED'
               GROUP BY oi.variant_id) AS r
          ON r.variant_id = i.variant_id
         SET i.quantity_reserved = i.quantity_reserved - r.qty
       WHERE i.warehouse_id = v_warehouse;

      -- … and the units leave the building through the ledger (trigger T1).
      INSERT INTO StockMovement (warehouse_id, variant_id, quantity_change, reason, movedAt, reference)
      SELECT v_warehouse, oi.variant_id, -oa.allocated_qty, 'SALE_SHIPMENT', NOW(), v_number
        FROM OrderAllocation oa
        JOIN OrderItem oi ON oi.order_item_id = oa.order_item_id
       WHERE oa.fulfillment_id = v_fulfillment
         AND oa.warehouse_id   = v_warehouse
         AND oa.status = 'RESERVED';

      UPDATE OrderAllocation
         SET status = 'SHIPPED', shipment_id = v_shipment
       WHERE fulfillment_id = v_fulfillment
         AND warehouse_id   = v_warehouse
         AND status = 'RESERVED';

      SET p_shipments = p_shipments + 1;
    END LOOP read_warehouse;
    CLOSE warehouse_cursor;
  END parcels;

  IF p_shipments = 0 THEN
    SET v_msg = CONCAT('Order ', v_number, ' has nothing left to ship.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  UPDATE Fulfillment
     SET status = 'SHIPPED', admin_id = COALESCE(admin_id, p_admin_id)
   WHERE fulfillment_id = v_fulfillment;

  UPDATE CustomerOrder SET status = 'SHIPPED' WHERE order_id = p_order_id;

  COMMIT;
END$$


-- -----------------------------------------------------------------------------
-- P5 · sp_start_fulfillment
-- A staff member takes a PLACED order: the fulfillment is assigned to them and
-- the order shows "Processing" (customers can no longer self-cancel).
-- -----------------------------------------------------------------------------
CREATE PROCEDURE sp_start_fulfillment(
  IN p_order_id  INT,
  IN p_admin_id  INT
)
MODIFIES SQL DATA
COMMENT 'Assign the packer; PLACED -> PROCESSING'
BEGIN
  DECLARE v_status VARCHAR(30);
  DECLARE v_number VARCHAR(50);
  DECLARE v_msg    VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT MAX(status), MAX(orderNumber) INTO v_status, v_number
    FROM CustomerOrder WHERE order_id = p_order_id FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Order not found.';
  ELSEIF v_status <> 'PLACED' THEN
    SET v_msg = CONCAT('Order ', v_number, ' is ', LOWER(v_status), '; only new orders can be started.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  UPDATE Fulfillment   SET admin_id = p_admin_id, status = 'PROCESSING' WHERE order_id = p_order_id;
  UPDATE CustomerOrder SET status = 'PROCESSING' WHERE order_id = p_order_id;

  COMMIT;
END$$


-- -----------------------------------------------------------------------------
-- P6 · sp_complete_return
-- Closes an APPROVED return once the parcel is back:
--   * optional restock: a RETURN_RESTOCK ledger row per line, into the
--     warehouse that shipped it (trigger T1 updates Inventory);
--   * one simulated REFUND transaction per line (Refund.transaction_id is
--     UNIQUE) for the historical price; trigger T3 re-checks every refund;
--   * the payment becomes PARTIALLY_REFUNDED or REFUNDED.
-- Set-based statements, no cursor: each line is independent.
-- -----------------------------------------------------------------------------
CREATE PROCEDURE sp_complete_return(
  IN  p_return_request_id  INT,
  IN  p_restock            BOOLEAN,
  OUT p_refund_total       DECIMAL(10,2)
)
MODIFIES SQL DATA
COMMENT 'Approved return -> optional restock + refunds; return becomes REFUNDED'
BEGIN
  DECLARE v_status   VARCHAR(30);
  DECLARE v_order    INT;
  DECLARE v_payment  INT;
  DECLARE v_amount   DECIMAL(10,2);
  DECLARE v_msg      VARCHAR(255);

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_refund_total = 0;

  START TRANSACTION;

  SELECT MAX(status), MAX(order_id) INTO v_status, v_order
    FROM ReturnRequest
   WHERE return_request_id = p_return_request_id
   FOR UPDATE;

  IF v_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Return not found.';
  ELSEIF v_status = 'REFUNDED' THEN
    SET v_msg = CONCAT('Return RMA-', p_return_request_id, ' was already refunded.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  ELSEIF v_status <> 'APPROVED' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Approve the return before refunding it.';
  END IF;

  SELECT MAX(payment_id) INTO v_payment
    FROM Payment
   WHERE order_id = v_order AND status IN ('CAPTURED', 'PARTIALLY_REFUNDED')
   FOR UPDATE;

  IF v_payment IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This order has no captured payment to refund.';
  END IF;

  IF (SELECT COUNT(*) FROM ReturnItem WHERE return_request_id = p_return_request_id) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This return has no items to refund.';
  END IF;

  IF p_restock THEN
    INSERT INTO StockMovement (warehouse_id, variant_id, quantity_change, reason, movedAt, reference)
    SELECT (SELECT MIN(oa.warehouse_id)
              FROM OrderAllocation oa
             WHERE oa.order_item_id = ri.order_item_id AND oa.status = 'SHIPPED'),
           oi.variant_id, ri.quantity, 'RETURN_RESTOCK', NOW(), CONCAT('RMA-', p_return_request_id)
      FROM ReturnItem ri
      JOIN OrderItem oi ON oi.order_item_id = ri.order_item_id
     WHERE ri.return_request_id = p_return_request_id;
  END IF;

  INSERT INTO `Transaction` (payment_id, transactionType, amount, status, reference)
  SELECT v_payment, 'REFUND', fn_refundable_amount(ri.return_item_id), 'SUCCESS',
         CONCAT('SIM-RFD-R', ri.return_item_id)
    FROM ReturnItem ri
   WHERE ri.return_request_id = p_return_request_id
     AND fn_refundable_amount(ri.return_item_id) > 0;

  -- Trigger T3 validates each of these rows.
  INSERT INTO Refund (return_item_id, transaction_id, amount, status)
  SELECT ri.return_item_id, t.transaction_id, t.amount, 'COMPLETED'
    FROM ReturnItem ri
    JOIN `Transaction` t ON t.reference = CONCAT('SIM-RFD-R', ri.return_item_id)
   WHERE ri.return_request_id = p_return_request_id;

  SELECT COALESCE(SUM(r.amount), 0) INTO p_refund_total
    FROM Refund r
    JOIN ReturnItem ri ON ri.return_item_id = r.return_item_id
   WHERE ri.return_request_id = p_return_request_id
     AND r.status = 'COMPLETED';

  SELECT amount INTO v_amount FROM Payment WHERE payment_id = v_payment;

  UPDATE Payment
     SET status = CASE WHEN fn_payment_refunded_total(v_payment) >= v_amount THEN 'REFUNDED'
                       WHEN fn_payment_refunded_total(v_payment) > 0         THEN 'PARTIALLY_REFUNDED'
                       ELSE 'CAPTURED' END
   WHERE payment_id = v_payment;

  UPDATE ReturnRequest
     SET status = 'REFUNDED', resolvedAt = NOW()
   WHERE return_request_id = p_return_request_id;

  COMMIT;
END$$

DELIMITER ;


-- >>> 04_triggers.sql
-- =============================================================================
-- MyEnterprise — File 04: triggers
-- -----------------------------------------------------------------------------
-- The three required triggers (T1–T3) each react to a data change:
--   T1 trg_stock_movement_apply     AFTER  INSERT StockMovement  → Inventory balance
--   T2 trg_return_item_validate     BEFORE INSERT ReturnItem     → return rules
--   T3 trg_refund_validate          BEFORE INSERT Refund         → refund limits
-- Supporting integrity triggers:
--   T4 trg_allocation_before_insert / trg_allocation_before_update
--                                   cross-table order consistency for allocations
--   T5 trg_warranty_claim_validate  BEFORE INSERT WarrantyClaim  → guarantee rules
--   T6 trg_shipment_delivered       AFTER  UPDATE Shipment       → order DELIVERED
--   T7 trg_stock_movement_no_update / trg_stock_movement_no_delete
--                                   the stock ledger is append-only
--
-- Rejections use SIGNAL SQLSTATE '45000' with a sentence the shop can show.
-- A SIGNAL inside a trigger cancels the whole statement that fired it
-- (InnoDB statement atomicity), so nothing half-applies.
-- =============================================================================

USE myenterprise;

DROP TRIGGER IF EXISTS trg_stock_movement_apply;
DROP TRIGGER IF EXISTS trg_return_item_validate;
DROP TRIGGER IF EXISTS trg_refund_validate;
DROP TRIGGER IF EXISTS trg_allocation_before_insert;
DROP TRIGGER IF EXISTS trg_allocation_before_update;
DROP TRIGGER IF EXISTS trg_warranty_claim_validate;
DROP TRIGGER IF EXISTS trg_shipment_delivered;
DROP TRIGGER IF EXISTS trg_stock_movement_no_update;
DROP TRIGGER IF EXISTS trg_stock_movement_no_delete;

DELIMITER $$

-- -----------------------------------------------------------------------------
-- T1 · trg_stock_movement_apply  (AFTER INSERT ON StockMovement)
-- The ledger drives the balance: every movement row changes
-- Inventory.quantity_on_hand by quantity_change, so on hand always equals the
-- sum of the ledger. Nobody updates quantity_on_hand directly.
--   * incoming stock: refused if the warehouse would exceed its capacity;
--     creates the Inventory row the first time a variant arrives;
--   * outgoing stock: refused if it would take on hand below zero or below
--     the units already reserved for customers.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_stock_movement_apply
AFTER INSERT ON StockMovement
FOR EACH ROW
BEGIN
  DECLARE v_on_hand   INT;
  DECLARE v_reserved  INT;
  DECLARE v_capacity  INT;
  DECLARE v_used      INT;
  DECLARE v_msg       VARCHAR(255);

  IF NEW.quantity_change > 0 THEN
    SELECT MAX(w.capacity) INTO v_capacity
      FROM Warehouse w WHERE w.warehouse_id = NEW.warehouse_id;
    SELECT COALESCE(SUM(i.quantity_on_hand), 0) INTO v_used
      FROM Inventory i WHERE i.warehouse_id = NEW.warehouse_id;

    IF v_used + NEW.quantity_change > v_capacity THEN
      SET v_msg = CONCAT('Warehouse is full: ', v_used, ' of ', v_capacity,
                         ' places used, cannot take ', NEW.quantity_change, ' more.');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;

    INSERT INTO Inventory (warehouse_id, variant_id, quantity_on_hand, quantity_reserved)
    VALUES (NEW.warehouse_id, NEW.variant_id, NEW.quantity_change, 0)
    ON DUPLICATE KEY UPDATE quantity_on_hand = quantity_on_hand + NEW.quantity_change;
  ELSE
    SELECT MAX(quantity_on_hand), MAX(quantity_reserved) INTO v_on_hand, v_reserved
      FROM Inventory
     WHERE warehouse_id = NEW.warehouse_id AND variant_id = NEW.variant_id;

    IF v_on_hand IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This warehouse holds no stock of that item.';
    END IF;

    IF v_on_hand + NEW.quantity_change < v_reserved THEN
      SET v_msg = CONCAT('Only ', v_on_hand - v_reserved, ' unreserved units on hand; cannot remove ',
                         -NEW.quantity_change, '.');
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
    END IF;

    UPDATE Inventory
       SET quantity_on_hand = quantity_on_hand + NEW.quantity_change
     WHERE warehouse_id = NEW.warehouse_id AND variant_id = NEW.variant_id;
  END IF;
END$$


-- -----------------------------------------------------------------------------
-- T2 · trg_return_item_validate  (BEFORE INSERT ON ReturnItem)
-- A return line is accepted only if:
--   * the order line belongs to the order named on the return request;
--   * the order was delivered, and the request is within 30 days of the
--     delivery of that item's parcel (requestedAt, so history re-validates);
--   * the units requested plus every earlier non-rejected return of the same
--     line do not exceed the units bought.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_return_item_validate
BEFORE INSERT ON ReturnItem
FOR EACH ROW
BEGIN
  DECLARE v_request_order  INT;
  DECLARE v_requested_at   DATETIME;
  DECLARE v_item_order     INT;
  DECLARE v_purchased      INT;
  DECLARE v_order_status   VARCHAR(30);
  DECLARE v_delivered_at   DATETIME;
  DECLARE v_already        INT;
  DECLARE v_msg            VARCHAR(255);

  SELECT MAX(order_id), MAX(requestedAt) INTO v_request_order, v_requested_at
    FROM ReturnRequest WHERE return_request_id = NEW.return_request_id;

  SELECT MAX(order_id), MAX(quantity) INTO v_item_order, v_purchased
    FROM OrderItem WHERE order_item_id = NEW.order_item_id;

  IF v_item_order IS NULL OR v_item_order <> v_request_order THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'That item is not part of the order being returned.';
  END IF;

  SELECT MAX(status) INTO v_order_status FROM CustomerOrder WHERE order_id = v_request_order;
  IF v_order_status <> 'DELIVERED' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only delivered orders can be returned.';
  END IF;

  SELECT MAX(s.deliveredAt) INTO v_delivered_at
    FROM OrderAllocation oa
    JOIN Shipment s ON s.shipment_id = oa.shipment_id
   WHERE oa.order_item_id = NEW.order_item_id AND s.status = 'DELIVERED';

  IF v_delivered_at IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'That item has not been delivered yet.';
  END IF;

  IF v_requested_at > v_delivered_at + INTERVAL 30 DAY THEN
    SET v_msg = CONCAT('The 30-day return window for this item closed on ',
                       DATE_FORMAT(v_delivered_at + INTERVAL 30 DAY, '%b %e, %Y'), '.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  SELECT COALESCE(SUM(ri.quantity), 0) INTO v_already
    FROM ReturnItem ri
    JOIN ReturnRequest rr ON rr.return_request_id = ri.return_request_id
   WHERE ri.order_item_id = NEW.order_item_id
     AND rr.status <> 'REJECTED';

  IF v_already + NEW.quantity > v_purchased THEN
    SET v_msg = CONCAT('Only ', GREATEST(v_purchased - v_already, 0), ' of ', v_purchased,
                       ' bought can still be returned.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;
END$$


-- -----------------------------------------------------------------------------
-- T3 · trg_refund_validate  (BEFORE INSERT ON Refund)
-- A refund is accepted only if:
--   * its return request is APPROVED (or already being refunded);
--   * the amount fits inside what is still refundable for that line
--     (returned units × historical price − earlier refunds; fn_refundable_amount);
--   * a linked transaction is a REFUND against a payment of the SAME order,
--     for the same amount, and the payment's refunds stay within the payment.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_refund_validate
BEFORE INSERT ON Refund
FOR EACH ROW
BEGIN
  DECLARE v_refundable    DECIMAL(10,2);
  DECLARE v_return_status VARCHAR(30);
  DECLARE v_return_order  INT;
  DECLARE v_tx_type       VARCHAR(30);
  DECLARE v_tx_amount     DECIMAL(10,2);
  DECLARE v_tx_order      INT;
  DECLARE v_pay_amount    DECIMAL(10,2);
  DECLARE v_pay_refunded  DECIMAL(10,2);
  DECLARE v_payment       INT;
  DECLARE v_msg           VARCHAR(255);

  SELECT MAX(rr.status), MAX(rr.order_id) INTO v_return_status, v_return_order
    FROM ReturnItem ri
    JOIN ReturnRequest rr ON rr.return_request_id = ri.return_request_id
   WHERE ri.return_item_id = NEW.return_item_id;

  IF v_return_status IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Refunds must belong to a return line.';
  ELSEIF v_return_status NOT IN ('APPROVED', 'REFUNDED') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Approve the return before refunding it.';
  END IF;

  SET v_refundable = fn_refundable_amount(NEW.return_item_id);
  IF NEW.amount > v_refundable THEN
    SET v_msg = CONCAT('Refund of $', FORMAT(NEW.amount, 2), ' is more than the $',
                       FORMAT(v_refundable, 2), ' still refundable for this item.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  IF NEW.transaction_id IS NOT NULL THEN
    SELECT MAX(t.transactionType), MAX(t.amount), MAX(p.order_id), MAX(p.payment_id), MAX(p.amount)
      INTO v_tx_type, v_tx_amount, v_tx_order, v_payment, v_pay_amount
      FROM `Transaction` t
      JOIN Payment p ON p.payment_id = t.payment_id
     WHERE t.transaction_id = NEW.transaction_id;

    IF v_tx_type IS NULL OR v_tx_type <> 'REFUND' THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A refund must be documented by a REFUND transaction.';
    END IF;
    IF v_tx_order <> v_return_order THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'That refund transaction belongs to a different order.';
    END IF;
    IF v_tx_amount <> NEW.amount THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Refund amount must match its transaction.';
    END IF;

    SET v_pay_refunded = fn_payment_refunded_total(v_payment);
    IF v_pay_refunded > v_pay_amount THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Refunds would exceed the amount paid for this order.';
    END IF;
  END IF;
END$$


-- -----------------------------------------------------------------------------
-- T4 · allocation consistency  (BEFORE INSERT / BEFORE UPDATE ON OrderAllocation)
-- Single foreign keys cannot prove that an allocation's order line, its
-- fulfillment and its shipment all belong to ONE order. These triggers do,
-- and stop an order line from being allocated beyond its quantity.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_allocation_before_insert
BEFORE INSERT ON OrderAllocation
FOR EACH ROW
BEGIN
  DECLARE v_item_order        INT;
  DECLARE v_item_qty          INT;
  DECLARE v_fulfillment_order INT;
  DECLARE v_allocated         INT;

  SELECT MAX(order_id), MAX(quantity) INTO v_item_order, v_item_qty
    FROM OrderItem WHERE order_item_id = NEW.order_item_id;
  SELECT MAX(order_id) INTO v_fulfillment_order
    FROM Fulfillment WHERE fulfillment_id = NEW.fulfillment_id;

  IF v_item_order IS NULL OR v_item_order <> v_fulfillment_order THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Allocation mixes lines from different orders.';
  END IF;

  SELECT COALESCE(SUM(allocated_qty), 0) INTO v_allocated
    FROM OrderAllocation
   WHERE order_item_id = NEW.order_item_id AND status <> 'RELEASED';

  IF v_allocated + NEW.allocated_qty > v_item_qty THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Allocation exceeds the quantity ordered.';
  END IF;
END$$

CREATE TRIGGER trg_allocation_before_update
BEFORE UPDATE ON OrderAllocation
FOR EACH ROW
BEGIN
  DECLARE v_shipment_fulfillment INT;

  IF NEW.order_item_id <> OLD.order_item_id OR NEW.fulfillment_id <> OLD.fulfillment_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'An allocation cannot move to another order.';
  END IF;

  IF NEW.shipment_id IS NOT NULL THEN
    SELECT MAX(fulfillment_id) INTO v_shipment_fulfillment
      FROM Shipment WHERE shipment_id = NEW.shipment_id;
    IF v_shipment_fulfillment IS NULL OR v_shipment_fulfillment <> NEW.fulfillment_id THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Shipment belongs to a different order.';
    END IF;
  END IF;

  IF OLD.status IN ('SHIPPED', 'RELEASED') AND NEW.status <> OLD.status THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Shipped or released allocations are final.';
  END IF;
END$$


-- -----------------------------------------------------------------------------
-- T5 · trg_warranty_claim_validate  (BEFORE INSERT ON WarrantyClaim)
--   * the guarantee must cover the exact variant that was bought;
--   * the item must be delivered, and the claim submitted before the
--     guarantee ends (fn_warranty_expires_on: delivery + duration);
--   * one open claim per order line at a time.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_warranty_claim_validate
BEFORE INSERT ON WarrantyClaim
FOR EACH ROW
BEGIN
  DECLARE v_warranty_variant INT;
  DECLARE v_item_variant     INT;
  DECLARE v_expires          DATE;
  DECLARE v_open             INT;
  DECLARE v_msg              VARCHAR(255);

  SELECT MAX(variant_id) INTO v_warranty_variant FROM Warranty WHERE warranty_id = NEW.warranty_id;
  SELECT MAX(variant_id) INTO v_item_variant FROM OrderItem WHERE order_item_id = NEW.order_item_id;

  IF v_warranty_variant IS NULL OR v_item_variant IS NULL OR v_warranty_variant <> v_item_variant THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This guarantee does not cover the item bought.';
  END IF;

  SET v_expires = fn_warranty_expires_on(NEW.order_item_id, NEW.warranty_id);
  IF v_expires IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The guarantee starts once the item is delivered.';
  END IF;
  IF DATE(NEW.submittedAt) > v_expires THEN
    SET v_msg = CONCAT('The quality guarantee for this item ended on ', DATE_FORMAT(v_expires, '%b %e, %Y'), '.');
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = v_msg;
  END IF;

  SELECT COUNT(*) INTO v_open
    FROM WarrantyClaim
   WHERE order_item_id = NEW.order_item_id AND status IN ('SUBMITTED', 'APPROVED');
  IF v_open > 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'There is already an open claim for this item.';
  END IF;
END$$


-- -----------------------------------------------------------------------------
-- T6 · trg_shipment_delivered  (AFTER UPDATE ON Shipment)
-- When the last parcel of an order is delivered (no parcel in transit and no
-- unit still reserved), the fulfillment completes and the order is DELIVERED.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_shipment_delivered
AFTER UPDATE ON Shipment
FOR EACH ROW
BEGIN
  DECLARE v_order       INT;
  DECLARE v_in_transit  INT;
  DECLARE v_reserved    INT;

  IF NEW.status = 'DELIVERED' AND OLD.status <> 'DELIVERED' THEN
    SELECT MAX(order_id) INTO v_order FROM Fulfillment WHERE fulfillment_id = NEW.fulfillment_id;

    SELECT COUNT(*) INTO v_in_transit
      FROM Shipment
     WHERE fulfillment_id = NEW.fulfillment_id AND status <> 'DELIVERED';
    SELECT COUNT(*) INTO v_reserved
      FROM OrderAllocation
     WHERE fulfillment_id = NEW.fulfillment_id AND status = 'RESERVED';

    IF v_in_transit = 0 AND v_reserved = 0 THEN
      UPDATE Fulfillment   SET status = 'COMPLETED' WHERE fulfillment_id = NEW.fulfillment_id;
      UPDATE CustomerOrder SET status = 'DELIVERED' WHERE order_id = v_order;
    END IF;
  END IF;
END$$


-- -----------------------------------------------------------------------------
-- T7 · the stock ledger is append-only
-- Mistakes are corrected with a new ADJUSTMENT row, never by editing history.
-- -----------------------------------------------------------------------------
CREATE TRIGGER trg_stock_movement_no_update
BEFORE UPDATE ON StockMovement
FOR EACH ROW
BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stock movements are permanent. Record an adjustment instead.';
END$$

CREATE TRIGGER trg_stock_movement_no_delete
BEFORE DELETE ON StockMovement
FOR EACH ROW
BEGIN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stock movements are permanent. Record an adjustment instead.';
END$$

DELIMITER ;


